    @Override public Map<String,Object> listPeriods(Integer year, String half, String status, String code, Integer pageNum, Integer pageSize) {
        int size = bounded(pageSize, 20, 1, 100), page = bounded(pageNum, 1, 1, 10000);
        StringBuilder where = new StringBuilder(" where record_origin='official' and status in ('draft','published')"); List<Object> args = new ArrayList<>();
        if (year != null) { where.append(" and exam_year=?"); args.add(year); }
        if (half != null) { where.append(" and half=?"); args.add(half); }
        if (status != null) { where.append(" and status=?"); args.add(status); }
        if (code != null && !code.isBlank()) { where.append(" and period_code=?"); args.add(code.trim()); }
        long total = jdbc.queryForObject("select count(*) from cm_exam_period" + where, Long.class, args.toArray());
        List<Map<String,Object>> rows = jdbc.queryForList("select id::text as \"id\",period_code as \"periodCode\",exam_year as \"examYear\",half,status,revision_no as \"revisionNo\",official_source_url as \"officialSourceUrl\",source_published_at as \"sourcePublishedAt\",row_version as \"rowVersion\",update_time as \"updatedTime\",(select count(*) from cm_exam_schedule s where s.exam_period_id=p.id) as \"scheduleCount\",(select count(*) from cm_exam_region_registration r where r.exam_period_id=p.id) as \"registrationCount\" from cm_exam_period p" + where + " order by exam_year desc,half desc,revision_no desc,id desc limit ? offset ?", with(args,size,(page-1)*size));
        return page(rows,total);
    }
    @Override public Map<String,Object> periodDetail(String id) { return detail(period(number(id))); }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> createPeriod(String request, JsonNode body) {
        return write("EXAM_GUIDANCE_CREATE_PERIOD",request,body,() -> {
            String code = required(body,"periodCode"); int year = requiredInt(body,"examYear"); String half = required(body,"half");
            if (!code.matches("^[0-9]{4}-H[12]$") || !code.equals(year + "-" + half) || year < LocalDate.now(SHANGHAI).getYear() || year > LocalDate.now(SHANGHAI).getYear()+3) throw invalid("periodCode","期次编码或年份不合法");
            Integer exists = jdbc.queryForObject("select count(*) from cm_exam_period where period_code=?",Integer.class,code); if (exists != null && exists > 0) throw conflict("EXAM_GUIDANCE_DUPLICATE_PERIOD","期次已存在");
            long id=IdUtil.getSnowflakeNextId(); jdbc.update("insert into cm_exam_period(id,period_code,exam_year,half,revision_no,record_origin,status,official_source_url,source_published_at,create_by,update_by) values(?,?,?,?,1,'official','draft',?,?,?,?)",id,code,year,half,https(body,"officialSourceUrl"),sourceTime(body),LoginHelper.getUserId(),LoginHelper.getUserId()); return detail(period(id));
        });
    }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> updatePeriod(String rawId,String request,JsonNode body) { long id=number(rawId); return write("EXAM_GUIDANCE_UPDATE_PERIOD",request,body,()->{ if(body.has("periodCode")||body.has("examYear")||body.has("half")) throw invalid("periodCode","更新不得修改期次编码、年份或半年度"); Map<String,Object> p=lockPeriod(id); draft(p,body); jdbc.update("update cm_exam_period set official_source_url=?,source_published_at=?,row_version=row_version+1,update_by=?,update_time=now() where id=?",https(body,"officialSourceUrl"),sourceTime(body),LoginHelper.getUserId(),id); return detail(period(id));}); }
    @Override @Transactional(rollbackFor=Exception.class) public void deletePeriod(String rawId,String request,JsonNode body) { long id=number(rawId); write("EXAM_GUIDANCE_DELETE_PERIOD",request,body,()->{Map<String,Object> p=period(id);draft(p,body);jdbc.update("delete from cm_exam_period where id=?",id);return Map.of();}); }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> createRevision(String rawId,String request,JsonNode body) { long sourceId=number(rawId); return write("EXAM_GUIDANCE_CREATE_REVISION",request,body,()->{Map<String,Object> source=lockPeriod(sourceId); version(source,body); if(!"published".equals(source.get("status"))) throw conflict("EXAM_GUIDANCE_STATE_CONFLICT","仅当前发布期次可复制"); Integer drafts=jdbc.queryForObject("select count(*) from cm_exam_period where period_code=? and status='draft'",Integer.class,source.get("period_code")); if(drafts != null && drafts > 0) throw conflict("EXAM_GUIDANCE_STATE_CONFLICT","当前发布期次已有修订草稿"); long id=IdUtil.getSnowflakeNextId(); int revision=((Number)jdbc.queryForObject("select max(revision_no)+1 from cm_exam_period where period_code=?",Integer.class,source.get("period_code"))).intValue(); jdbc.update("insert into cm_exam_period(id,period_code,exam_year,half,revision_no,supersedes_period_id,record_origin,status,official_source_url,source_published_at,create_by,update_by) select ?,period_code,exam_year,half,?,id,'official','draft',official_source_url,source_published_at,?,? from cm_exam_period where id=?",id,revision,LoginHelper.getUserId(),LoginHelper.getUserId(),sourceId); copyChildren(sourceId,id); return detail(period(id));}); }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> publish(String rawId,String request,JsonNode body) { long id=number(rawId); return write("EXAM_GUIDANCE_PUBLISH",request,body,()->{Map<String,Object> p=period(id);draft(p,body); Integer schedules=jdbc.queryForObject("select count(*) from cm_exam_schedule where exam_period_id=?",Integer.class,id); Integer sessions=jdbc.queryForObject("select count(*) from cm_exam_schedule_session ss join cm_exam_schedule s on s.id=ss.exam_schedule_id where s.exam_period_id=?",Integer.class,id); Integer registrations=jdbc.queryForObject("select count(*) from cm_exam_region_registration where exam_period_id=?",Integer.class,id); if(schedules==0||sessions==0||registrations==0) throw new CertMuseApiException(422,"EXAM_GUIDANCE_PUBLISH_INCOMPLETE","期次缺少资格、场次或报名信息"); jdbc.update("update cm_exam_period set status='superseded',update_time=now() where period_code=? and status='published'",p.get("period_code")); jdbc.update("update cm_exam_period set status='published',published_by=?,published_time=now(),row_version=row_version+1,update_by=?,update_time=now() where id=?",LoginHelper.getUserId(),LoginHelper.getUserId(),id); Map<String,Object> result=new LinkedHashMap<>();result.put("periodId",String.valueOf(id));result.put("periodCode",p.get("period_code"));result.put("revisionNo",p.get("revision_no"));result.put("status","published");result.put("rowVersion",((Number)p.get("row_version")).longValue()+1);return result;}); }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> saveSchedule(String periodRaw,String scheduleRaw,String request,JsonNode body) { return write(scheduleRaw==null?"EXAM_GUIDANCE_CREATE_SCHEDULE":"EXAM_GUIDANCE_UPDATE_SCHEDULE",request,body,()->{long scheduleId=scheduleRaw==null?IdUtil.getSnowflakeNextId():number(scheduleRaw); long periodId=scheduleRaw==null?number(periodRaw):((Number)one("select exam_period_id from cm_exam_schedule where id=?",number(scheduleRaw)).get("exam_period_id")).longValue(); Map<String,Object> p=period(periodId);draft(p,body,"expectedPeriodRowVersion"); long certification=number(required(body,"certificationId")); Integer eligible=jdbc.queryForObject("select count(*) from cm_exam_certification where id=? and status='0'",Integer.class,certification);if(eligible==null||eligible==0)throw invalid("certificationId","资格必须为启用状态"); JsonNode sessions=body.path("sessions"); if(!sessions.isArray()||sessions.isEmpty()) throw invalid("sessions","至少需要一个场次"); LocalDate start=null,end=null; for(JsonNode s:sessions){OffsetDateTime a=time(s,"startTime"),b=time(s,"endTime");if(!b.isAfter(a))throw invalid("sessions","结束时间必须晚于开始时间");LocalDate d=a.atZoneSameInstant(SHANGHAI).toLocalDate();if(!((String)p.get("half")).equals(d.getMonthValue()<=6?"H1":"H2"))throw invalid("sessions","场次开始时间不属于期次半年度");start=start==null||d.isBefore(start)?d:start;LocalDate e=b.atZoneSameInstant(SHANGHAI).toLocalDate();end=end==null||e.isAfter(end)?e:end;}
            if(scheduleRaw==null) jdbc.update("insert into cm_exam_schedule(id,certification_id,revision_no,exam_date,exam_period_id,exam_start_date,exam_end_date,public_note,status) values(?,?,1,?,?,?,?,?, 'draft')",scheduleId,certification,start,periodId,start,end,text(body,"publicNote")); else {jdbc.update("delete from cm_exam_schedule_session where exam_schedule_id=?",scheduleId);jdbc.update("update cm_exam_schedule set certification_id=?,exam_date=?,exam_start_date=?,exam_end_date=?,public_note=? where id=?",certification,start,start,end,text(body,"publicNote"),scheduleId);} for(JsonNode s:sessions) jdbc.update("insert into cm_exam_schedule_session(id,exam_schedule_id,exam_subject_id,certification_id,session_code,start_time,end_time,sort_order) values(?,?,?,?,?,?,?,?)",IdUtil.getSnowflakeNextId(),scheduleId,number(required(s,"examSubjectId")),certification,required(s,"sessionCode"),time(s,"startTime"),time(s,"endTime"),s.path("sortOrder").asInt()); bump(periodId);return Map.of("periodId",String.valueOf(periodId),"scheduleId",String.valueOf(scheduleId),"periodRowVersion",versionOf(periodId));}); }
    @Override @Transactional(rollbackFor=Exception.class) public Map<String,Object> deleteSchedule(String raw,String request,JsonNode body){return write("EXAM_GUIDANCE_DELETE_SCHEDULE",request,body,()->{long id=number(raw),periodId=((Number)one("select exam_period_id from cm_exam_schedule where id=?",id).get("exam_period_id")).longValue();draft(period(periodId),body,"expectedPeriodRowVersion");jdbc.update("delete from cm_exam_schedule where id=?",id);bump(periodId);return Map.of("periodId",String.valueOf(periodId),"deletedScheduleId",String.valueOf(id),"periodRowVersion",versionOf(periodId));});}
    @Override public Map<String,Object> listRegions(String keyword,String status,String type,Integer pageNum,Integer pageSize){
        int size=bounded(pageSize,20,1,100),page=bounded(pageNum,1,1,10000);StringBuilder where=new StringBuilder(" where 1=1");List<Object> args=new ArrayList<>();
        if(keyword!=null&&!keyword.isBlank()){String term="%"+keyword.trim()+"%";where.append(" and (region_name ilike ? or region_code ilike ?)");args.add(term);args.add(term);}
        if(status!=null&&!status.isBlank()){where.append(" and status=?");args.add(status);}
        if(type!=null&&!type.isBlank()){where.append(" and region_type=?");args.add(type);}
        long total=jdbc.queryForObject("select count(*) from cm_exam_region"+where,Long.class,args.toArray());
        return page(jdbc.queryForList("select id::text as \"id\",region_code as \"regionCode\",region_name as \"regionName\",region_type as \"regionType\",parent_region_code as \"parentRegionCode\",institution_name as \"institutionName\",contact_phone as \"contactPhone\",local_notice_url as \"localNoticeUrl\",sort_order as \"sortOrder\",status,row_version as \"rowVersion\",update_time as \"updatedTime\" from cm_exam_region"+where+" order by sort_order,id limit ? offset ?",with(args,size,(page-1)*size)),total);
    }
