    private void copyChildren(long sourceId,long targetId){
        for(Map<String,Object> source:jdbc.queryForList("select * from cm_exam_schedule where exam_period_id=? order by id",sourceId)){
            long newId=IdUtil.getSnowflakeNextId(), oldId=((Number)source.get("id")).longValue();
            jdbc.update("insert into cm_exam_schedule(id,certification_id,revision_no,exam_date,exam_period_id,exam_start_date,exam_end_date,public_note,copied_from_id,status) values(?,?,1,?,?,?,?,?,?,'draft')",newId,source.get("certification_id"),source.get("exam_date"),targetId,source.get("exam_start_date"),source.get("exam_end_date"),source.get("public_note"),oldId);
            for(Map<String,Object> session:jdbc.queryForList("select * from cm_exam_schedule_session where exam_schedule_id=? order by id",oldId)) jdbc.update("insert into cm_exam_schedule_session(id,exam_schedule_id,exam_subject_id,certification_id,session_code,start_time,end_time,sort_order) values(?,?,?,?,?,?,?,?)",IdUtil.getSnowflakeNextId(),newId,session.get("exam_subject_id"),session.get("certification_id"),session.get("session_code"),session.get("start_time"),session.get("end_time"),session.get("sort_order"));
        }
        for(Map<String,Object> reg:jdbc.queryForList("select * from cm_exam_region_registration where exam_period_id=? order by id",sourceId)) jdbc.update("insert into cm_exam_region_registration(id,exam_period_id,region_id,registration_start,registration_end,review_start,review_end,payment_start,payment_end,qualification_review_note,payment_note,official_source_url,source_published_at,copied_from_id,create_by,update_by) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",IdUtil.getSnowflakeNextId(),targetId,reg.get("region_id"),reg.get("registration_start"),reg.get("registration_end"),reg.get("review_start"),reg.get("review_end"),reg.get("payment_start"),reg.get("payment_end"),reg.get("qualification_review_note"),reg.get("payment_note"),reg.get("official_source_url"),reg.get("source_published_at"),reg.get("id"),LoginHelper.getUserId(),LoginHelper.getUserId());
    }
    private Map<String,Object> period(long id){return one("select * from cm_exam_period where id=?",id);} private Map<String,Object> lockPeriod(long id){return one("select * from cm_exam_period where id=? for update",id);} private Map<String,Object> region(long id){return one("select id,region_code as \"regionCode\",region_name as \"regionName\",region_type as \"regionType\",parent_region_code as \"parentRegionCode\",institution_name as \"institutionName\",contact_phone as \"contactPhone\",local_notice_url as \"localNoticeUrl\",sort_order as \"sortOrder\",status,row_version as \"rowVersion\",update_time as \"updatedTime\" from cm_exam_region where id=?",id);} private Map<String,Object> one(String sql,Object... args){try{return jdbc.queryForMap(sql,args);}catch(EmptyResultDataAccessException e){throw new CertMuseApiException(404,"EXAM_GUIDANCE_RESOURCE_NOT_FOUND","资源不存在");}}
    private Map<String, Object> write(String action, String request, JsonNode body, Supplier<Map<String, Object>> work) {
        String key = requestId(request);
        String hash = DigestUtil.sha256Hex(body.toString());
        List<Map<String, Object>> existing = jdbc.queryForList(
            "select payload_hash,status,response_body from cm_idempotency_record where action_code=? and request_id=?", action, key);
        if (!existing.isEmpty()) {
            Map<String, Object> record = existing.getFirst();
            if (!hash.equals(record.get("payload_hash"))) throw conflict("EXAM_GUIDANCE_IDEMPOTENCY_CONFLICT", "请求号载荷不一致");
            if ("processing".equals(record.get("status"))) {
                throw new CertMuseApiException(409, "EXAM_GUIDANCE_REQUEST_IN_PROGRESS", "请求处理中", true, null, List.of(), null, null);
            }
            try {
                return jsonMapper.treeToValue(jsonMapper.readTree((String) record.get("response_body")).path("response").path("data"), Map.class);
            } catch (Exception exception) {
                throw new CertMuseApiException(500, "EXAM_GUIDANCE_SYSTEM_FAILURE", "读取幂等响应失败");
            }
        }
        jdbc.update("insert into cm_idempotency_record(id,action_code,request_id,payload_hash,status,resource_type,expires_time) values(?,?,?,?, 'processing','exam_guidance',now()+interval '24 hours')",
            IdUtil.getSnowflakeNextId(), action, key, hash);
        Map<String, Object> result = work.get();
        try {
            String envelope = VersionedJsonDocumentFactory.json(jsonMapper, CatalogJsonSchema.EXAM_GUIDANCE_IDEMPOTENCY,
                Map.of("response", Map.of("data", result)));
            jdbc.update("update cm_idempotency_record set status='succeeded',response_status=200,response_body=cast(? as jsonb),update_time=now() where action_code=? and request_id=?",
                envelope, action, key);
        } catch (Exception exception) {
            throw new CertMuseApiException(500, "EXAM_GUIDANCE_SYSTEM_FAILURE", "保存幂等响应失败");
        }
        return result;
    }
